fn solve(x: i32) -> i32 {
    // Convert x to string to easily access digits and length
    let s = x.to_string();
    let digit = s.chars().next().unwrap().to_digit(10).unwrap() as i32;
    let k = s.len() as i32;

    // Calculate the score
    // For each digit before the current one, we typed 1+2+3+4 = 10 presses
    let presses_before_digit = (digit - 1) * 10;
    // For the current digit, we typed 1+2+...+(k-1) presses before the k-length number
    let presses_for_current_digit = (k * (k + 1)) / 2;

    presses_before_digit + presses_for_current_digit
}